<div class="form-card"><p class="eyebrow">Sales</p><h1>Record Sale</h1><?php if($errors): ?><div class="errors"><ul><?php foreach($errors as $e): ?><li><?= esc($e) ?></li><?php endforeach; ?></ul></div><?php endif; ?><form method="post" action="<?= site_url('sales/new') ?>"><label for="product_id">Product</label><select id="product_id" name="product_id" required><option value="">Choose a product</option><?php foreach($products as $p): ?><option value="<?= $p['id'] ?>"><?= esc($p['name']) ?> — ₱<?= number_format($p['price'],2) ?> (<?= $p['stock_quantity'] ?> available)</option><?php endforeach; ?></select><label for="customer_id">Customer (optional)</label><select id="customer_id" name="customer_id"><option value="">Walk-in customer</option><?php foreach($customers as $c): ?><option value="<?= $c['id'] ?>"><?= esc($c['full_name']) ?></option><?php endforeach; ?></select><label for="quantity">Quantity</label><input id="quantity" name="quantity" type="number" min="1" step="1" required><div class="form-actions"><button class="button" type="submit">Complete Sale</button><a class="button button-secondary" href="<?= site_url('sales') ?>">Cancel</a></div></form></div>
